CREATE TABLE Parent (
  OrgID STRING(36) NOT NULL,
  ParentID STRING(36) NOT NULL,
  Name STRING(MAX) NOT NULL,
  Status INT64 NOT NULL,
) PRIMARY KEY(OrgID, ParentID);

CREATE INDEX ParentByName ON Parent(OrgID, Name);

CREATE TABLE Child (
  OrgID STRING(36) NOT NULL,
  ParentID STRING(36) NOT NULL,
  ChildID STRING(36) NOT NULL,
  Value STRING(MAX) NOT NULL,
) PRIMARY KEY(OrgID, ParentID, ChildID),
INTERLEAVE IN PARENT Parent ON DELETE CASCADE;

CREATE INDEX ChildByValue ON Child(OrgID, Value);

CREATE TABLE Gen (
  ID STRING(36) NOT NULL,
  Phone STRING(MAX) NOT NULL,
  Digits STRING(MAX) AS (REGEXP_REPLACE(Phone, r'[^0-9]', '')) STORED,
  Count INT64 NOT NULL DEFAULT (0),
) PRIMARY KEY(ID);

CREATE INDEX GenByDigits ON Gen(Digits);
